import com.mushafi.app.AppUpdatePolicy;
import java.io.*;import java.security.*;import java.nio.file.*;
public class UpdatePolicyChecks {
 static void need(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static void rejected(String url,String sha,long size){try{new AppUpdatePolicy(156,"3.1.6",23,url,sha,size);throw new AssertionError("Unsafe manifest accepted");}catch(IllegalArgumentException expected){}}
 public static void main(String[]args)throws Exception{byte[] bytes=new byte[1000000];java.util.Arrays.fill(bytes,(byte)42);String sha=AppUpdatePolicy.hex(MessageDigest.getInstance("SHA-256").digest(bytes)),url=AppUpdatePolicy.ORIGIN+"/download/Mushafi-3.1.6.apk";AppUpdatePolicy release=new AppUpdatePolicy(156,"3.1.6",23,url,sha,bytes.length);need(release.newerThan(155,23),"available release");need(!release.newerThan(156,36),"same version");need(!release.newerThan(157,36),"downgrade");need(!release.newerThan(155,22),"unsupported SDK");for(String bad:new String[]{url.replace("https:","http:"),url.replace(AppUpdatePolicy.HOST,"example.org"),url+"?target=other",url+"#bad",url.replace("/download/","/other/"),url.replace("3.1.6.apk","3.1.5.apk"),url.replace(AppUpdatePolicy.HOST,"user@"+AppUpdatePolicy.HOST),url.replace(AppUpdatePolicy.HOST,AppUpdatePolicy.HOST+":443")})rejected(bad,sha,bytes.length);rejected(url,"bad-hash",bytes.length);rejected(url,sha,999);File file=File.createTempFile("mushafi-update-test",".apk");try{Files.write(file.toPath(),bytes);release.verify(file);bytes[500]=43;Files.write(file.toPath(),bytes);try{release.verify(file);throw new AssertionError("Tampering accepted");}catch(IOException expected){}Files.write(file.toPath(),new byte[1]);try{release.verify(file);throw new AssertionError("Truncation accepted");}catch(IOException expected){}}finally{file.delete();}System.out.println("PASS: trusted HTTPS host/path, version downgrade and SDK guards, manifest validation, full byte checksum, tamper and truncation rejection");}
}
